PLACE_ANGLE_OFFSET = 0.0

# 吸盘中心相对法兰 Z 轴的偏心（mm，机器人基坐标 XY，在抓取姿态 TCP_RPY 下测得的向量）。
# 有偏心时，放置阶段绕 Z 旋转 delta 会让块中心偏离规划点：
#   偏差 = (R(delta) - I)·offset，大小约 2|offset|·sin(|delta|/2)
# plan_puzzle 会按 delta 反补该位移；默认 (0,0) 表示不补偿，与旧行为完全一致。
# 测量：保持抓取姿态记录吸盘尖端位置 → 只把末端绕 Z 轴转 180° → 再记录一次 →
#       offset = (第一次 - 第二次)/2；也可用实测落点反解：
#       python -m scenarios.tangram_puzzle.tool_offset_check --estimate 实测.csv
SUCTION_OFFSET_XY = (0.0, 0.0)

# ---- 相机标定 ----
CAMERA_MATRIX = np.array([[911.150042904, 0.0, 645.508361552],
                          [0.0, 910.404783297, 364.917563218],
                          [0.0, 0.0, 1.0]])
