    template_roi=(898, 162, 354, 452),
    min_fit_iou=0.85,
    conflict_overlap=0.20,
    required_ids=(1, 2, 3, 4, 5, 6, 7),
    min_area=500,                  # 单色掩模内有效轮廓的最小面积 px²
    morph_size=7,                  # 开/闭运算核尺寸，切断块间阴影细缝
    # ---- 判据加固（2026-10-26 实测后加入，可用开关一键回到旧行为）----
    # 两种现场失效都源于"身份判据绑在照明相关的单点阈值上"：
    #   ① 橙色(V>=200) 与 咖啡色(V<=199) 只差 1 个灰阶——暗光下橙块 V 掉到 194，
    #      87% 的像素落进咖啡色掩模，导致橙丢失 + 咖啡"多候选"；
